/* Reputation management service presentation. No Google account actions. */
const reputationModes={
 single:{title:'One location. A clear starting point.',copy:'We check the existing listing, who controls it and what customers can see. Then agree the access, verification support and upkeep your business needs.',items:['Find the right profile before creating anything new','Confirm business details and owner access','Plan verification support around Google’s available method','Agree who approves updates and sensitive replies']},
 multi:{title:'Several locations. One organised plan.',copy:'A business with branches in Kingston, Mandeville and Montego Bay needs accurate local details, not the same information copied everywhere. We organise the work location by location.',items:['Record each eligible location and its access status','Check branch hours, phone numbers, images and details','Coordinate local staff and physical visits where needed','Review verification progress and ongoing responsibilities separately']}
};
function reputationPlan(mode){const p=reputationModes[mode];return `<span class="eyebrow">Illustrative service plan</span><h3>${p.title}</h3><p>${p.copy}</p><ul>${p.items.map(t=>`<li>${t}</li>`).join('')}</ul><p class="micro">Eligibility, travel, locations covered and service fees are agreed in advance. A visit is not automatically required for every location.</p>`;}
const reputationBridge=()=>section(`<div class="rp-bridge"><div><span class="eyebrow">After the appointment / Reviews & reputation</span><h2>The visit ends.<br>The conversation continues.</h2><p>Invite an honest review after a completed service, with an appropriate configured request. For hands-on help with your Google profile, verification, updates and review responses, explore our additional managed service.</p><a href="#/reputation" class="button blue">Explore reputation management <span>→</span></a></div><div class="rp-bridge-flow"><span>Service completed</span><b>↓</b><span>Honest review invitation</span><b>↓</b><span>Listen, respond and improve</span></div></div>`,'rp-appointment-bridge');
const reputationAppointmentsBase=pages.appointments;
pages.appointments=()=>{const html=reputationAppointmentsBase();const end=html.lastIndexOf('<section class="cta">');return end>=0?html.slice(0,end)+reputationBridge()+html.slice(end):html+reputationBridge();};
pages.reputation=()=>`<section class="rp-hero"><div class="wrap"><div><a class="breadcrumb" href="#/platform">AyudaGrow / Reputation management</a><span class="eyebrow">Google Business Profile + ongoing care</span><h1>Your reputation.<br><em>Worth looking after.</em></h1><p>Your customers may already be talking about your business. If you don’t control your Google profile, you could be missing the chance to respond.</p><div class="actions"><a href="#/contact" class="button">Let’s review your profile <span>→</span></a><button type="button" class="textlink rp-jump" data-reputation-jump>Explore the service ↓</button></div><span class="rp-service-tag">Additional managed service · scope and fees agreed separately</span></div><div class="rp-profile-art" role="img" aria-label="Illustration of a business profile connected to accurate details, updates and thoughtful responses"><div class="rp-window"><div class="rp-window-head"><i></i><i></i><i></i><span>YOUR BUSINESS, IN VIEW</span></div><div class="rp-store"><span>YOUR BUSINESS</span><div class="rp-awning"></div><div class="rp-storefront"><i></i><b></b><i></i></div></div><div class="rp-profile-lines"><b>A useful first impression.</b><span>Accurate hours</span><span>Recent images</span><span>Thoughtful responses</span></div></div><img src="assets/mascot-wave.png" alt=""/><div class="rp-art-label">A profile is a starting point.<br><b>Care keeps it useful.</b></div></div></div></section>`+
section(`<div id="rp-service" class="section-head"><div><span class="eyebrow">More than asking for reviews</span><h2>Claim it. Care for it.<br>Stay part of the conversation.</h2></div><p>From access and verification support to regular updates and customer feedback, AyudaGrow helps you look after the profile people find before they contact you.</p></div><div class="rp-service-grid">${[
['01','Get access sorted','Find an existing profile, check ownership and help with the appropriate claim or access-request process. Avoid creating a duplicate when a listing already exists.'],
['02','Support verification','Help prepare the business information and evidence for the method Google offers. Coordinate with your team and visit physical locations where needed and agreed.'],
['03','Keep the details current','Manage approved hours, holiday changes, contact details, images and suitable posts. Agree the content, update frequency and approval process.'],
['04','Respond with care','Monitor reviews within agreed service hours, prepare or publish authorised replies, and send complaints or sensitive issues to the right person.'],
['05','Invite honest feedback','Configure suitable review requests after completed services, with appropriate communication permissions and a neutral invitation to all eligible customers.'],
['06','Keep improving the process','Review recurring feedback, missed updates and unresolved issues with your team. Use what customers say to inform practical service improvements.']
].map(([n,h,p])=>`<article><span>${n}</span><h3>${h}</h3><p>${p}</p></article>`).join('')}</div>`)+
section(`<div class="rp-access"><div><span class="eyebrow">The profile may already be there</span><h2>Customers don’t wait<br>for you to claim it.</h2><p>A business listing can already exist, with customer reviews, before you claim or verify it. Claiming your profile is about managing your business presence, not switching reviews on for the first time.</p><p>Google requires business verification before you can reply to reviews as the business. We start by checking the existing profile and access situation, then help with the next appropriate step.</p><a href="https://support.google.com/business/answer/3474050?no_link=1" class="textlink" target="_blank" rel="noopener noreferrer">Google’s guidance on replying to reviews ↗</a></div><aside class="rp-owner-note"><span class="eyebrow">Your business stays yours</span><h3>You keep ownership.<br>We support the work.</h3><p>Use the appropriate manager access for the agreed service. Your business retains primary ownership. You don’t need to hand over your password.</p><p>Keep verification codes private. The owner completes any steps Google requires them to perform.</p><a href="https://support.google.com/business/answer/3403100?hl=en-11" class="textlink" target="_blank" rel="noopener noreferrer">How Google owner and manager roles work ↗</a></aside></div>`,'how')+
section(`<div class="section-head"><div><span class="eyebrow">Practical help, on the ground when needed</span><h2>One location or several.<br>Support that fits the work.</h2></div><p>Remote guidance may be enough. When physical support is needed, we can plan visits with the people who know the premises, including across multiple locations.</p></div><div class="rp-location-layout"><div class="rp-location-art" aria-label="Illustrative branches in Jamaica, not actual client locations"><div class="rp-location-line"></div><span class="rp-location"><b>01</b>Kingston<small>Profile & access</small></span><span class="rp-location"><b>02</b>Mandeville<small>Local details</small></span><span class="rp-location"><b>03</b>Montego Bay<small>Location support</small></span><p>Different branches.<br><strong>Details that belong to each one.</strong></p></div><div><div class="rp-mode-controls" role="group" aria-label="Explore location support"><button type="button" data-reputation-mode="single" aria-pressed="true" aria-controls="rp-location-plan">One location</button><button type="button" data-reputation-mode="multi" aria-pressed="false" aria-controls="rp-location-plan">Multiple locations</button></div><div id="rp-location-plan" class="rp-location-plan" aria-live="polite">${reputationPlan('single')}</div></div></div><div class="rp-boundary"><b>Google decides the verification method and outcome.</b><p>The available options depend on the business and profile. We support the process; we cannot choose a method Google hasn’t offered or guarantee approval, timing or that a visit will resolve an issue.</p><a href="https://support.google.com/business/answer/7107242?external_link=true" target="_blank" rel="noopener noreferrer">Read Google’s verification guidance ↗</a></div>`)+
section(`<div class="section-head"><div><span class="eyebrow">Customer feedback deserves a real response</span><h2>Listen first.<br>Choose the right next step.</h2></div><p>A thank-you, a correction and a serious complaint need different handling. Agree the tone, response permissions and escalation path before replies go out.</p></div><div class="rp-response-grid"><article><span class="rp-response-symbol">♡</span><h3>Everyday feedback</h3><p>Acknowledge the experience with a relevant, approved response. Avoid copying the same generic answer onto every review.</p><b>Thoughtful reply</b></article><article><span class="rp-response-symbol">↗</span><h3>A concern to resolve</h3><p>Flag the issue to the business owner or named lead. Keep private details out of public replies and move sensitive discussion to an appropriate private channel.</p><b>Human escalation</b></article><article><span class="rp-response-symbol">⚑</span><h3>A possible policy violation</h3><p>Assess it against Google’s policies and help report it where appropriate. A negative review alone is not grounds for removal; Google decides.</p><b>Policy-based reporting</b></article></div><p class="micro">AI may assist with drafts where configured. People remain responsible for factual accuracy, privacy and authorised publication. Monitoring frequency and response targets are agreed, not assumed to be 24/7.</p>`,'rp-response-section')+
section(`<div class="rp-review-flow"><div><span class="eyebrow">Connect the service to the follow-through</span><h2>An invitation.<br>Not an expectation<br>of five stars.</h2><p>After a completed appointment or service, a configured workflow can invite customers to share their genuine experience. The customer chooses whether to respond and what to say.</p><a href="#/appointments" class="textlink">See the appointment journey →</a></div><div class="rp-invitation"><span class="eyebrow">Illustrative review request</span><p>“Thank you for visiting us. If you’d like to share your experience, you can leave an honest review using this link. We appreciate your feedback.”</p><div>Completed service → Appropriate invitation → Customer’s choice</div><small>Sample wording only. No message is sent from this preview.</small></div></div><div class="rp-fairness"><b>Keep it fair.</b><p>No incentives, pressure or requests for a particular rating. No screening out unhappy customers or only inviting positive reviews. Configure timing, recipients, permissions, opt-outs and channel costs before activation.</p><a href="https://support.google.com/contributionpolicy/answer/7400114?LanguageId=1" target="_blank" rel="noopener noreferrer">Google’s review content policy ↗</a></div>`)+
section(`<div class="rp-scope"><div><span class="eyebrow">Clear scope. Clear responsibilities.</span><h2>A managed service,<br>agreed separately.</h2><p>This hands-on service is additional to platform access. Having review tools in a plan does not automatically include profile claiming, verification assistance, location visits, content management or review-response work.</p><p>We confirm what you need, what your team supplies and what AyudaGrow will manage before work starts.</p><a href="#/contact" class="button">Discuss your profile and locations <span>→</span></a></div><ul><li><b>Locations & starting point</b><span>Which profiles, access issues and verification steps are in scope.</span></li><li><b>Hands-on work</b><span>Visits, travel, images, posts and update frequency.</span></li><li><b>Review handling</b><span>Monitoring times, authorised replies and escalation owners.</span></li><li><b>Fees & dependencies</b><span>Service fees, platform requirements and any messaging usage charges.</span></li></ul></div>`,'rp-scope-section')+
section(`<div class="section-head"><h2>Before we get started.</h2></div><div class="ib-faq"><details><summary>Can you guarantee verification, rankings or more positive reviews?</summary><p>No. Google controls verification, moderation and visibility. Customers control their reviews. Our service is the practical work of keeping your presence accurate, helping with the available processes and responding responsibly.</p></details><details><summary>Do all locations need an in-person visit?</summary><p>No. We review each location’s situation and the verification options Google provides. Physical visits are arranged where needed and agreed, with access, staff availability and travel planned beforehand.</p></details><details><summary>Will you remove negative reviews?</summary><p>We can help assess and report reviews that appear to breach Google’s policies. We cannot remove legitimate criticism or promise Google will remove a reported review. We also help the business respond and address issues that need attention.</p></details><details><summary>What if someone else already controls the profile?</summary><p>Start with the existing profile and the appropriate Google ownership or access-request process. We help identify the next step rather than creating a second listing to work around the issue.</p></details></div><p class="micro rp-sources">Service copy is a review draft. Google controls feature eligibility and policies. Guidance checked against Google’s <a href="https://support.google.com/business/answer/3039617?hl=en-en" target="_blank" rel="noopener noreferrer">profile editing</a>, <a href="https://support.google.com/business/answer/7342169" target="_blank" rel="noopener noreferrer">posts</a> and <a href="https://support.google.com/business/answer/3474122?gl=US&hl=en" target="_blank" rel="noopener noreferrer">review best practices</a> documentation.</p>`);
const reputationPriorWiring=wireExpanded;wireExpanded=function(){reputationPriorWiring();document.querySelector('[data-reputation-jump]')?.addEventListener('click',()=>document.getElementById('rp-service').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'}));document.querySelectorAll('[data-reputation-mode]').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('[data-reputation-mode]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));document.getElementById('rp-location-plan').innerHTML=reputationPlan(b.dataset.reputationMode);}));};
render();
